source.bookSourceComment:
大神吧小说 - 智能翻页
章节≥100自动递增: xxx.html → xxx/index_2.html

.page-link.0@text##.*\/(\d+)$##$1
@js:
res = JSON.parse(result)
list = [];
for (var i = 2; i <= res; i++) {
    // 将 .html 或 .htm 扩展名替换为 /，然后拼接 index_i.html
    list.push(baseUrl.replace(/\.html?$/, '/') + "index_" + i + ".html");
}
list;

ruleToc.nextTocUrl:
@js:{
    var nextUrl = '';
    try {
        var doc = org.jsoup.Jsoup.parse(result);
        var count = doc.select('.book_list2 > ul > li').size();
        if (count >= 100) {
            var url = baseUrl;
            if (url.indexOf('index_') > 0) {
                var numMatch = /index_(\d+)\.html/.exec(url);
                if (numMatch) {
                    var num = parseInt(numMatch[1]) + 1;
                    nextUrl = url.replace(/index_(\d+)\.html/, 'index_' + num + '.html');
                }
            } else if (url.endsWith('.html')) {
                nextUrl = url.replace(/\.html$/, '/index_2.html');
            }
        }
    } catch (e) {}
    nextUrl;
}

